using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class YachtAtlasValidation{const string D="Assets/Scenes/Oasis/YachtPortAtlas";static YachtAtlasValidation(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("YachtAtlasValidation.request"))return;File.Delete("YachtAtlasValidation.request");var mat=AssetDatabase.LoadAssetAtPath<Material>(D+"/Shared Yacht Yard Atlas.mat");int other=0,renderers=0;foreach(string path in Enumerable.Range(1,6).Select(i=>"Assets/Scenes/Oasis/SouthBeach/Docking Pier "+i+".prefab").Concat(new[]{D+"/Yatch_Port Detailed.prefab"})){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(path);foreach(var r in prefab.GetComponentsInChildren<MeshRenderer>()){renderers++;other+=r.sharedMaterials.Count(m=>m!=mat);}}var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var yard=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads").GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Yatch_Port");var original=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/3D/Prefeb/Roads.prefab").GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Yatch_Port");var data=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{original.sharedMesh});var vertices=(Vector3[])data.GetType().GetField("p").GetValue(data);var ids=(int[])data.GetType().GetField("ids").GetValue(data);bool exact=yard.sharedMesh.vertices.SequenceEqual(vertices)&&yard.sharedMesh.triangles.SequenceEqual(ids);var p=yard.sharedMesh.vertices.Select(yard.transform.TransformPoint).ToArray();var n=yard.sharedMesh.normals.Select(yard.transform.TransformDirection).ToArray();var top=p.Where((v,i)=>n[i].y>.8f).ToArray();var point=top.OrderBy(v=>(new Vector2(v.x,v.z)-new Vector2(275,-675)).sqrMagnitude).First();typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,point+new Vector3(-10,12,-13),point+new Vector3(8,0,8),"Yatch-Port-Atlas-Closeup"});File.WriteAllText("FinalEnvironmentRoadReview/YachtAtlasValidation.txt","prefab renderers="+renderers+"; non-shared material references="+other+"; original yard vertices and indices exact="+exact+"; shader errors="+ShaderUtil.GetShaderMessages(mat.shader).Count(m=>m.severity.ToString()=="Error"));}}
